cd /private/tmp/claude-501/-Users-knitresletta-prosjekter-claude-portfolio/7d8c75c5-3309-4349-9151-b06f649a2b20/scratchpad && cat > shot.mjs <<'EOF'
import { createRequire } from "node:module";
const require = createRequire("/Users/knitresletta/.npm/_npx/9833c18b2d85bc59/node_modules/");
const { chromium, devices } = require("playwright-core");
const exe = "/Users/knitresletta/Library/Caches/ms-playwright/chromium_headless_shell-1234/chrome-headless-shell-mac-arm64/chrome-headless-shell";
const site = "file:///Users/knitresletta/prosjekter/claude/portfolio/";
const pages = ["index.html", "dev.html", "musikk.html", "om-meg.html"];
const browser = await chromium.launch({ executablePath: exe });
for (const [label, ctxOpts] of [["desktop", { viewport: { width: 1280, height: 900 } }], ["mobil", devices["iPhone 13"]]]) {
  const ctx = await browser.newContext(ctxOpts);
  const page = await ctx.newPage();
  for (const p of pages) {
    await page.goto(site + p, { waitUntil: "networkidle" });
    await page.waitForTimeout(600);
    const over = await page.evaluate(() => document.documentElement.scrollWidth - document.documentElement.clientWidth);
    const broken = await page.evaluate(() => [...document.images].filter(i => !i.complete || i.naturalWidth === 0).map(i => i.getAttribute("src")));
    console.log(`${label} ${p}: overflow=${over}px brokenImgs=${JSON.stringify(broken)}`);
    await page.screenshot({ path: `${label}-${p.replace(".html", "")}.png`, fullPage: true });
  }
  await ctx.close();
}
await browser.close();
EOF
node shot.mjs && ls *.png

